import type { HandlerInterface } from './handlers.js'
import type { JSONRespond } from './handlers.js'

/**
 * The application router. Every HTTP verb is declared as a property whose type
 * is an interface alias, so this file names the verbs but carries no call
 * signature for any of them.
 */
export declare class AppBase<E extends Env, BasePath extends string = '/'> {
    get: HandlerInterface<E, 'get', BasePath>;
    post: HandlerInterface<E, 'post', BasePath>;
    delete: HandlerInterface<E, 'delete', BasePath>;
    json: JSONRespond;
}

export interface Env {
    Bindings: Record<string, unknown>;
}
